99	/** Throws away a failed attempt's partial work so a retry starts from the setup commit. */
100	function resetTo(sandboxPath: string, setupSha: string): void {
101	  gitOk(sandboxPath, ["reset", "-q", "--hard", setupSha]);
102	  gitOk(sandboxPath, ["clean", "-qfdx"]);
103	}
